-- Upstream PostgreSQL incremental initialization data
-- Source: sql/postgresql/ruoyi-vue-pro.sql
-- Menu diff: c21eef8602e0 (2026-09-18) -> e83c142831b0 (2026-09-22).
-- Dictionary diff: 7358ff9b5a21 (2026-07-01) -> e83c142831b0 (2026-09-22).
-- Inserts only records absent by business key. Existing records are never updated or deleted.
-- Scope: menus, dictionary types/values, and active super-admin menu bindings.
-- Excludes: business tables, users, departments, ordinary roles, permissions and scheduled jobs.
-- Execute while the application is stopped. Any error rolls back the full transaction.

BEGIN;
SET LOCAL search_path TO mes, public;
LOCK TABLE system_menu, system_dict_type, system_dict_data, system_role_menu, system_role IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE _upstream_id_state (next_menu_id bigint NOT NULL, next_dict_type_id bigint NOT NULL, next_dict_data_id bigint NOT NULL, next_role_menu_id bigint NOT NULL) ON COMMIT DROP;

-- 837 source menu nodes (766 distinct menu business keys) plus 9 required ancestor directories.
CREATE TEMP TABLE _upstream_menu_source (LIKE system_menu) ON COMMIT DROP;
ALTER TABLE _upstream_menu_source ADD COLUMN source_id bigint PRIMARY KEY;
ALTER TABLE _upstream_menu_source ADD COLUMN source_parent_id bigint NOT NULL;
ALTER TABLE _upstream_menu_source ADD COLUMN source_depth integer NOT NULL;

CREATE TEMP TABLE _upstream_menu_map (source_id bigint PRIMARY KEY, target_id bigint NOT NULL) ON COMMIT DROP;
DO $$
DECLARE source_menu record; actual_parent_id bigint; actual_id bigint;
BEGIN
  FOR source_menu IN SELECT * FROM _upstream_menu_source ORDER BY source_depth, source_id LOOP
    actual_parent_id := 0;
    IF source_menu.source_parent_id <> 0 THEN
      SELECT target_id INTO actual_parent_id FROM _upstream_menu_map WHERE source_id = source_menu.source_parent_id;
      IF actual_parent_id IS NULL THEN RAISE EXCEPTION 'Missing parent mapping for upstream menu % (parent %)', source_menu.source_id, source_menu.source_parent_id; END IF;
    END IF;
    actual_id := NULL;
    IF COALESCE(source_menu.permission, '') <> '' THEN
      SELECT id INTO actual_id FROM system_menu WHERE deleted='0' AND parent_id=actual_parent_id AND permission=source_menu.permission AND name=source_menu.name ORDER BY id LIMIT 1;
    ELSIF COALESCE(source_menu.component, '') <> '' THEN
      SELECT id INTO actual_id FROM system_menu WHERE deleted='0' AND parent_id=actual_parent_id AND component=source_menu.component AND name=source_menu.name ORDER BY id LIMIT 1;
    ELSE
      SELECT id INTO actual_id FROM system_menu WHERE deleted='0' AND parent_id=actual_parent_id AND path=source_menu.path AND name=source_menu.name ORDER BY id LIMIT 1;
    END IF;
    IF actual_id IS NULL THEN
      SELECT next_menu_id INTO actual_id FROM _upstream_id_state;
      UPDATE _upstream_id_state SET next_menu_id=next_menu_id+1;
    END IF;
  END LOOP;
END $$;

-- Give imported menu entries to active super administrators only.
WITH candidates AS (
 SELECT role.id role_id,role.tenant_id,map.target_id menu_id,ROW_NUMBER() OVER(ORDER BY role.id,map.target_id) sequence_no FROM system_role role CROSS JOIN _upstream_menu_map map
 WHERE role.code='super_admin' AND role.deleted='0' AND NOT EXISTS(SELECT 1 FROM system_role_menu b WHERE b.role_id=role.id AND b.menu_id=map.target_id AND b.deleted='0')
)
SELECT s.next_role_menu_id+c.sequence_no-1,c.role_id,c.menu_id,'admin',CURRENT_TIMESTAMP,'admin',CURRENT_TIMESTAMP,'0',c.tenant_id FROM candidates c CROSS JOIN _upstream_id_state s;
UPDATE _upstream_id_state SET next_role_menu_id=COALESCE((SELECT MAX(id) FROM system_role_menu),0)+1;

-- 159 dictionary types.
CREATE TEMP TABLE _upstream_dict_type_source (LIKE system_dict_type) ON COMMIT DROP;

WITH candidates AS (SELECT source.*,ROW_NUMBER() OVER(ORDER BY source.type) sequence_no FROM _upstream_dict_type_source source WHERE NOT EXISTS(SELECT 1 FROM system_dict_type target WHERE target.type=source.type))
UPDATE _upstream_id_state SET next_dict_type_id=COALESCE((SELECT MAX(id) FROM system_dict_type),0)+1;

-- 648 dictionary values, including the one added on 2026-09-04.
CREATE TEMP TABLE _upstream_dict_data_source (LIKE system_dict_data) ON COMMIT DROP;

WITH candidates AS (SELECT source.*,ROW_NUMBER() OVER(ORDER BY source.dict_type,source.value,source.sort,source.label) sequence_no FROM _upstream_dict_data_source source WHERE NOT EXISTS(SELECT 1 FROM system_dict_data target WHERE target.dict_type=source.dict_type AND target.value=source.value))
COMMIT;
